SourceCode.Declaration:
/// <summary>
/// One record per game played in the form <c>DEVTutorialArcadeGames</c>.
/// The JavaScript games write to this table through the X++ commands of <c>DEVTutorialArcadeControl</c>:
/// GameStarted inserts the record, ScoreChanged updates the live score and GameOver saves the result.
/// </summary>
public class DEVTutorialArcadeSession extends common
{
}

Method.Source:
/// <summary>
/// Finds a session by record ID.
/// </summary>
/// <param name = "_recId">The record ID.</param>
/// <param name = "_forUpdate">true to select the record for update.</param>
/// <returns>The session; an empty buffer if not found.</returns>
public static DEVTutorialArcadeSession find(RecId _recId, boolean _forUpdate = false)
{
    DEVTutorialArcadeSession session;

    if (_recId)
    {
        session.selectForUpdate(_forUpdate);

        select firstonly session
            where session.RecId == _recId;
    }

    return session;
}

/// <summary>
/// Inserts a running session for the current user.
/// </summary>
/// <param name = "_game">The game that was started.</param>
/// <returns>The record ID of the new session.</returns>
/// <remarks>
/// Sessions of the user that are still running were abandoned (e.g. the browser page was reloaded,
/// which does not run the form's close method), so they are closed as stopped first.
/// </remarks>
public static RecId startSession(DEVTutorialArcadeGame _game)
{
    DEVTutorialArcadeSession session, lastSession;
    UserId                   userId = curUserId();
    utcdatetime              now    = DateTimeUtil::utcNow();

    ttsbegin;
    update_recordset session
        setting Status      = DEVTutorialArcadeSessionStatus::Stopped,
                EndDateTime = now,
                Details     = '{"reason":"abandoned"}'
        where session.UserId == userId
           && session.Status == DEVTutorialArcadeSessionStatus::Running;

    // the player's game number: 1 for the first round of this game, then 2, 3, ...
    select maxof(GameNum) from lastSession
        where lastSession.UserId == userId
           && lastSession.Game   == _game;

    session.clear();
    session.Game          = _game;
    session.GameNum       = lastSession.GameNum + 1;
    session.UserId        = curUserId();
    session.StartDateTime = DateTimeUtil::utcNow();
    session.Status        = DEVTutorialArcadeSessionStatus::Running;
    session.insert();
    ttscommit;

    return session.RecId;
}

/// <summary>
/// Writes the live score of a running session.
/// </summary>
/// <param name = "_recId">The session.</param>
/// <param name = "_score">The current score.</param>
public static void updateScore(RecId _recId, int _score)
{
    DEVTutorialArcadeSession session;

    ttsbegin;
    session = DEVTutorialArcadeSession::find(_recId, true);
    if (session.RecId && session.Status == DEVTutorialArcadeSessionStatus::Running)
    {
        session.Score = _score;
        session.update();
    }
    ttscommit;
}

/// <summary>
/// Saves the result of a running session.
/// </summary>
/// <param name = "_recId">The session.</param>
/// <param name = "_score">The final score.</param>
/// <param name = "_status">Finished or Stopped.</param>
/// <param name = "_details">Result details sent by the game (JSON).</param>
public static void endSession(RecId _recId, int _score, DEVTutorialArcadeSessionStatus _status, str _details)
{
    DEVTutorialArcadeSession session;

    ttsbegin;
    session = DEVTutorialArcadeSession::find(_recId, true);
    if (session.RecId && session.Status == DEVTutorialArcadeSessionStatus::Running)
    {
        session.Score       = _score;
        session.Status      = _status;
        session.EndDateTime = DateTimeUtil::utcNow();
        session.Details     = subStr(_details, 1, 255);
        session.update();
    }
    ttscommit;
}

/// <summary>
/// Gets the best score of a user in a game.
/// </summary>
/// <param name = "_game">The game.</param>
/// <param name = "_userId">The user; the current user by default.</param>
/// <returns>The highest score of the user's completed sessions.</returns>
public static int bestScore(DEVTutorialArcadeGame _game, UserId _userId = curUserId())
{
    DEVTutorialArcadeSession session;

    select maxof(Score) from session
        where session.Game   == _game
           && session.UserId == _userId
           && session.Status != DEVTutorialArcadeSessionStatus::Running;

    return session.Score;
}

/// <summary>
/// Gets the name of the player.
/// </summary>
/// <returns>The user name, or the user ID when the user has no name.</returns>
public display UserName userName()
{
    UserInfo userInfo;

    select firstonly name from userInfo
        where userInfo.id == this.UserId;

    return userInfo.name ? userInfo.name : this.UserId;
}

/// <summary>
/// Gets the play time as minutes:seconds.
/// </summary>
/// <returns>The play time; empty while the session is running.</returns>
public display Name durationText()
{
    int64 seconds;

    if (this.EndDateTime == utcDateTimeNull())
    {
        return '';
    }

    seconds = DateTimeUtil::getDifference(this.EndDateTime, this.StartDateTime);

    return strFmt('%1:%2', seconds div 60, num2Str0(seconds mod 60, 2));
}
